import ee
ee.Initialize(project='earthsense-436113')

# 1. Define Great Lakes geometries (approximate bounding boxes)
lake_erie = ee.Geometry.Polygon([
    [[-83.5, 41.4], [-80.8, 41.4], [-80.8, 42.8], [-83.5, 42.8], [-83.5, 41.4]]
])

lake_superior = ee.Geometry.Polygon([
    [[-89.8, 46.5], [-84.3, 46.5], [-84.3, 48.3], [-89.8, 48.3], [-89.8, 46.5]]
])

lake_michigan = ee.Geometry.Polygon([
    [[-87.5, 41.7], [-85.0, 41.7], [-85.0, 48.3], [-87.5, 48.3], [-87.5, 41.7]]
])

lake_huron = ee.Geometry.Polygon([
    [[-84.9, 43.8], [-82.0, 43.8], [-82.0, 46.0], [-84.9, 46.0], [-84.9, 43.8]]
])

lake_ontario = ee.Geometry.Polygon([
    [[-79.8, 43.2], [-76.6, 43.2], [-76.6, 44.0], [-79.8, 44.0], [-79.8, 43.2]]
])

lakes = {
    'Erie': lake_erie,
    'Superior': lake_superior,
    'Michigan': lake_michigan,
    'Huron': lake_huron,
    'Ontario': lake_ontario
}

# 2. Load Landsat 8 for Feb 14, 2018
start_date = '2018-02-14'
end_date = '2018-02-15'

col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2') \
    .filterDate(start_date, end_date) \
    .filterMetadata('WRS_PATH', 'not_in', [1, 2])  # Exclude polar orbits

print(f"Landsat 8 images available: {col.size().getInfo()}")

if col.size().getInfo() == 0:
    print("No Landsat 8 data found for Feb 14, 2018")
    print("C1")
else:
    # 3. Function to calculate NDSI (Normalized Difference Snow Index)
    # NDSI = (Green - SWIR) / (Green + SWIR)
    # For LS8: Band 3 (Green), Band 6 (SWIR-1)
    def add_ndsi(img):
        green = img.select('SR_B3').float()
        swir = img.select('SR_B6').float()
        ndsi = green.subtract(swir).divide(green.add(swir)).rename('NDSI')
        return img.addBands(ndsi)

    # Function to mask clouds using QA_PIXEL
    def mask_clouds(img):
        qa = img.select('QA_PIXEL')
        # Mask clouds and cloud shadows
        cloud_mask = qa.bitwiseAnd(32).eq(0).And(qa.bitwiseAnd(64).eq(0))
        return img.updateMask(cloud_mask)

    col = col.map(mask_clouds).map(add_ndsi)

    # 4. Calculate ice coverage for each lake
    results = {}
    for lake_name, geom in lakes.items():
        # Use first available image that has data over this lake
        valid_img = col.filterBounds(geom).first()

        if valid_img is None:
            results[lake_name] = {'ice_pct': None, 'pixels': 0}
            continue

        # Count total valid pixels
        total_pixels = valid_img.select('NDSI').reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=300,
            maxPixels=1e9
        ).get('NDSI').getInfo()

        if total_pixels is None or total_pixels == 0:
            results[lake_name] = {'ice_pct': 0, 'pixels': 0}
            continue

        # Count ice pixels (NDSI > 0.4 is typical for snow/ice)
        ice_mask = valid_img.select('NDSI').gt(0.4)
        ice_pixels = ice_mask.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=300,
            maxPixels=1e9
        ).get('NDSI').getInfo()

        ice_pct = (ice_pixels / total_pixels) * 100 if total_pixels > 0 else 0
        results[lake_name] = {'ice_pct': ice_pct, 'pixels': total_pixels}

    # 5. Print results and determine answer
    print("\nIce Coverage (Feb 14, 2018):")
    for lake, data in results.items():
        pct = data['ice_pct']
        if pct is not None:
            print(f"{lake}: {pct:.1f}% (valid pixels: {int(data['pixels'])})")
        else:
            print(f"{lake}: No data")

    # Check if any lake has valid data
    valid_lakes = {k: v for k, v in results.items() if v['ice_pct'] is not None}

    if len(valid_lakes) == 0:
        print("C2")
    else:
        erie_ice = results['Erie']['ice_pct']
        other_ice = [v['ice_pct'] for k, v in results.items() 
                     if k != 'Erie' and v['ice_pct'] is not None]

        if erie_ice is None or len(other_ice) == 0:
            print("C3")
        elif erie_ice > max(other_ice):
            print("A")
        else:
            print("B")
